node -e "
const fs=require('fs'),path=require('path'),http=require('http');
const root='c:/Users/james/Videos/deeds-web-app/sveltekit-frontend';
const lines=[];

// 1. Audit gates from latest run
try{
  const runs=fs.readdirSync(path.join(root,'memory/runs')).sort().filter(d=>d.match(/^\d{4}/));
  const run=runs[runs.length-1];
  if(run){
    const gf=path.join(root,'memory/runs',run,'audit_gates.json');
    if(fs.existsSync(gf)&&(Date.now()-fs.statSync(gf).mtimeMs)<86400000){
      const g=JSON.parse(fs.readFileSync(gf,'utf8'));
      const fails=Object.entries(g.gates||{}).filter(([k,v])=>typeof v==='number'&&v>0&&!k.includes('consumer')&&!k.includes('pass')&&!k.includes('kmeans')&&!k.includes('som'));
      if(fails.length) lines.push('OPEN AUDIT GATES: '+fails.map(([k,v])=>k+'='+v).join(', '));
      else lines.push('Audit gates: ALL PASS (run '+run+')');
    }
  }
}catch(e){}

// 2. codebase-graph.json age
try{
  const gj=path.join(root,'docs/graph/codebase-graph.json');
  if(fs.existsSync(gj)){
    const age=Math.round((Date.now()-fs.statSync(gj).mtimeMs)/60000);
    lines.push('codebase-graph.json age: '+age+'min'+(age>120?' ⚠️ stale':''));
  }
}catch(e){}

// 3. Service health (non-blocking, 300ms timeout each)
const probe=(port,path,label)=>new Promise(resolve=>{
  const req=http.get({hostname:'127.0.0.1',port,path,timeout:300},r=>resolve(label+':'+r.statusCode));
  req.on('error',()=>resolve(label+':down'));
  req.on('timeout',()=>{req.destroy();resolve(label+':timeout');});
});
Promise.all([
  probe(8090,'/health','turbo'),
  probe(3040,'/health','bifrost'),
  probe(8788,'/health','mcp'),
  probe(5173,'/api/health','sveltekit'),
]).then(statuses=>{
  const up=statuses.filter(s=>s.includes(':200')||s.includes(':204')).map(s=>s.split(':')[0]);
  const down=statuses.filter(s=>!s.includes(':200')&&!s.includes(':204')).map(s=>s.split(':')[0]);
  if(up.length) lines.push('Services UP: '+up.join(', '));
  if(down.length) lines.push('Services DOWN: '+down.join(', ')+' (start via tasks.json or start-trace-stack.ps1)');
  if(lines.length) console.log(JSON.stringify({systemMessage:'[Graph context] '+lines.join(' | ')}));
}).catch(()=>{
  if(lines.length) console.log(JSON.stringify({systemMessage:'[Graph context] '+lines.join(' | ')}));
});
" 2>/dev/null

